import { describe, expect, it } from 'vitest';
import {
  canonicalCaseKey,
  namespaceIdForCase,
  type GoldenCaseMeta,
} from './goldenCase.ts';
import { formatGoldenPhp, parseGoldenPhp } from './goldenPhp.ts';

const intMeta: GoldenCaseMeta = { input: 'int', output: 'function' };

const intExpected = `/** @phpstan-assert-if-true int $value */
function isInt(mixed $value): bool
{
    return is_int($value);
}
`;

const stringExpected = `/** @phpstan-assert-if-true string $value */
function isString(mixed $value): bool
{
    return is_string($value);
}
`;

describe('namespaceIdForCase', () => {
  it('hashes case identity via node:crypto, not the body', () => {
    const a = namespaceIdForCase(intMeta);
    const b = namespaceIdForCase({
      input: 'int',
      output: 'function',
    });
    expect(a).toBe(b);
    expect(a).toMatch(/^h[a-f0-9]{12}$/u);
    expect(canonicalCaseKey(intMeta)).toBe(
      JSON.stringify({
        input: 'int',
        output: 'function',
        emitPhpstanTypeAliases: false,
        verbosePhpdoc: false,
        sealArrayShapes: false,
      }),
    );
  });

  it('keeps distinct namespaces for same body with different inputs', () => {
    const trueId = namespaceIdForCase({ input: 'true', output: 'function' });
    const trueCaseId = namespaceIdForCase({
      input: 'TRue',
      output: 'function',
    });
    expect(trueId).not.toBe(trueCaseId);
  });

  it('includes options in the namespace id', () => {
    const base = namespaceIdForCase({
      input: 'array{foo: int}',
      output: 'function',
    });
    const sealed = namespaceIdForCase({
      input: 'array{foo: int}',
      output: 'function',
      sealArrayShapes: true,
    });
    expect(base).not.toBe(sealed);
  });
});

describe('formatGoldenPhp header', () => {
  it('emits Go-style generated comment and strict_types', () => {
    const source = formatGoldenPhp('function', [
      { meta: intMeta, expected: intExpected },
    ]);
    expect(source.startsWith('<?php\n')).toBe(true);
    expect(source).toContain(
      '// Code generated by yarn update_fixtures:generator; DO NOT EDIT.',
    );
    expect(source).toContain(
      '// Generator success fixtures for function.IN.',
    );
    expect(source).toContain('declare(strict_types = 1);');
    expect(source).toMatch(/^\/\/ Code generated .* DO NOT EDIT\.$/mu);
  });

  it('round-trips an empty suite (header only)', () => {
    const source = formatGoldenPhp('empty_suite', []);
    expect(parseGoldenPhp(source)).toEqual([]);
    expect(source).toContain(
      '// Generator success fixtures for empty_suite.IN.',
    );
  });
});

describe('formatGoldenPhp round-trip', () => {
  it('preserves bodies and namespace ids', () => {
    const source = formatGoldenPhp('function', [
      { meta: intMeta, expected: intExpected },
      {
        meta: { input: 'string', output: 'function' },
        expected: stringExpected,
      },
    ]);
    const cases = parseGoldenPhp(source);
    expect(cases).toHaveLength(2);
    expect(cases[0]).toMatchObject({
      meta: intMeta,
      expected: intExpected,
      namespaceId: namespaceIdForCase(intMeta),
    });
    expect(cases[1]?.meta.input).toBe('string');
  });

  it('records 1-based line ranges', () => {
    const source = formatGoldenPhp('function', [
      { meta: intMeta, expected: intExpected },
    ]);
    const cases = parseGoldenPhp(source);
    expect(cases).toHaveLength(1);
    expect(cases[0]?.startLine).toBe(8);
    expect(cases[0]?.endLine).toBe(16);
  });
});

describe('formatGoldenPhp options and errors', () => {
  it('round-trips sparse option flags and multiline input', () => {
    const meta: GoldenCaseMeta = {
      input: '/**\n * @phpstan-type Foo int\n */',
      output: 'public_static',
      emitPhpstanTypeAliases: true,
      verbosePhpdoc: true,
    };
    const expected = `class TypeChecker\n{\n}\n`;
    const source = formatGoldenPhp('docblock', [{ meta, expected }]);
    expect(source).toContain('"emitPhpstanTypeAliases":true');
    expect(source).toContain('"verbosePhpdoc":true');
    expect(source).not.toContain('sealArrayShapes');
    const [parsed] = parseGoldenPhp(source);
    expect(parsed?.meta).toEqual(meta);
    expect(parsed?.expected).toBe(expected);
  });

  it('dedupes identical cases when formatting', () => {
    const source = formatGoldenPhp('function', [
      { meta: intMeta, expected: intExpected },
      { meta: intMeta, expected: intExpected },
    ]);
    expect(parseGoldenPhp(source)).toHaveLength(1);
  });

  it('rejects mismatched namespace ids when parsing', () => {
    const source = formatGoldenPhp('function', [
      { meta: intMeta, expected: intExpected },
    ]);
    const broken = source.replace(
      /namespace Golden\\h[a-f0-9]{12}/u,
      'namespace Golden\\h000000000000',
    );
    expect(() => parseGoldenPhp(broken)).toThrow(/namespace id mismatch/u);
  });
});
